SELECT pspf.PORTFOLIO_ID, pspf.FINPROD_ID, pspf.SEC_ACCT_ID, pspf.CCY,
pspf.INV_AIM, CASE WHEN ava.INV_AIM = #{INV_AIM_AC} THEN 1 WHEN ava.INV_AIM = #{INV_AIM_FVOCI} THEN 2 WHEN ava.INV_AIM = #{INV_AIM_FVTPL} THEN 3 ELSE 0 END invAimSort,
SUM(NVL(pspf.AMOUNT, 0)) AMOUNT FROM PTL_SEC_POSITION_FLOW pspf LEFT JOIN TRD_STASEC_FLOW tsf ON tsf.SEQNO = pspf.TRADE_ID AND tsf.PORTFOLIO_ID = pspf.PORTFOLIO_ID AND tsf.SEC_ACCT_ID = pspf.SEC_ACCT_ID WHERE pspf.HODING_TYPE = #{POSITION_TYPE_04} AND tsf.SEQNO IS NOT NULL AND tsf.SEQNO != ''
AND pspf.PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR}
AND pspf.SEC_ACCT_ID = #{secAcctId, jdbcType=VARCHAR}
AND pspf.FINPROD_ID = #{finProdId, jdbcType=VARCHAR}
AND TO_CHAR(pspf.CDATE, 'yyyy-MM-dd') <= #{searchDate, jdbcType=VARCHAR}
GROUP BY pspf.PORTFOLIO_ID, pspf.FINPROD_ID, pspf.SEC_ACCT_ID, pspf.CCY
,pspf.INV_AIM

select T1.* from TRD_PRODUCT_DEAL T1 LEFT JOIN TRD_PRODUCT_DEAL_ADD T2 ON T1.trade_id = t2.trade_id LEFT JOIN PTL_PORTFOLIO T3 ON T3.PORTFOLIO_ID = T2.PORTFOLIO_ID WHERE T3.PARENT_PORTFOLIO_ID IS NULL
and TOTLE_TRADE_ID = #{totleTradeId}
and TRADE_ID = #{tradeId}

